// sound.js - 音效與背景音樂(全域 window.Sound, 不用 ES module)
// 事件名、呼叫時機與 opts 見 sound.md; RD 只需讀 sound.md。
(function () {
  'use strict';

  var PCM_RATE = 22050;
  var MUSIC_VOL = 0.7;
  var SONG_START_BEAT = -4;   // 每首歌的第 0 秒 = 該關時鐘第 -4 拍(預備拍第一拍)

  // ---- 背景音樂資訊(數值由量測得出, 見 sound.md) ----
  // lead: 檔案開頭的數位靜音秒數; onset: 原始輸出檔中第一個 |樣本| > 0.02 的時間(用來自動校正解碼器的開頭填充)
  // songSec: 歌曲長度(預備拍 1 小節 + 關長小節); loop: 循環區段(相對歌曲第 0 秒的秒數), null = 不循環(目前三首都不循環)
  var MUSIC = {
    // 第 1 關: Voice Over Under(Kevin MacLeod)原 135 BPM, 保留音高放慢到 105
    stage1: { file: 'music_stage1.mp3', bpm: 105, bars: 37, levelBars: 36, lead: 0.05, onset: 0.050522, songSec: 84.571429, loop: null },
    // 第 2 關: Litany to the Datastream Goddess v1.11(FoxSynergy)原 128 BPM, 保留音高放慢到 115; 截原曲第 68~108 小節
    stage2: { file: 'music_stage2.mp3', bpm: 115, bars: 41, levelBars: 40, lead: 0.05, onset: 0.050635, songSec: 85.565217, loop: null },
    // 第 3 關: Thy Steel Consumed(FoxSynergy)原 120 BPM, 保留音高加快到 125; 截原曲第 64~112 小節; 不循環(播完一輪就過關)
    stage3: { file: 'music_stage3.mp3', bpm: 125, bars: 49, levelBars: 48, lead: 0.05, onset: 0.050726, songSec: 94.080000, loop: null }
  };
  (function () {
    for (var k in MUSIC) {
      if (!Object.prototype.hasOwnProperty.call(MUSIC, k)) continue;
      var m = MUSIC[k];
      m.beatSec = 60 / m.bpm;
      m.offset = m.lead;        // 解碼後歌曲第 0 秒在 buffer 裡的位置(解碼後自動校正)
    }
  })();

  // ---- 一次性音效定義 ----
  // pcm: 內嵌 PCM 名稱; file: 沒有 Web Audio 時的退路檔; vol: 相對音量
  var SFX = {
    countIn:     { pcm: 'count_in_pluck',      file: 'count_in_pluck.mp3',      vol: 0.8 },
    onBeat:      { pcm: 'on_beat_glass',       file: 'on_beat_glass.mp3',       vol: 0.85 },
    beatChain:   { pcm: 'beat_chain_powerup',  file: 'beat_chain_powerup.mp3',  vol: 0.9 },
    catch:       { pcm: 'catch_confirm',       file: 'catch_confirm.mp3',       vol: 0.45 },
    netSwap:     { pcm: 'net_swap_phaser_up',  file: 'net_swap_phaser_up.mp3',  vol: 0.4 },
    expire:      { pcm: 'expire_phaser_down',  file: 'expire_phaser_down.mp3',  vol: 0.5 },
    danger:      { pcm: 'danger_jingle',       file: 'danger_jingle.mp3',       vol: 0.65 },
    stageChange: { pcm: 'stage_change_steel',  file: 'stage_change_steel.mp3',  vol: 0.6 },
    floorRotate: { pcm: 'floor_rotate_switch', file: 'floor_rotate_switch.mp3', vol: 1.0 },
    wrongDye:    { pcm: 'wrong_dye_error',     file: 'wrong_dye_error.mp3',     vol: 0.4 },
    // v20 新手教學: 提示彈出(輕、短的「啵」)與階段完成(明亮短閃音), 都比遊戲回饋音低調
    tutorialShow: { pcm: 'tutorial_show_drop',    file: 'tutorial_show_drop.mp3',    vol: 0.35 },
    tutorialDone: { pcm: 'tutorial_done_confirm', file: 'tutorial_done_confirm.mp3', vol: 0.3 }
  };
  // 預備拍: 剩 4 / 3 / 2 / 1 拍時的音高(do re mi so, 越接近開始越高)
  var COUNT_IN_RATE = { 4: 1.0, 3: 1.1225, 2: 1.2599, 1: 1.4983 };
  // 踩拍 3 級: 每層 [音高倍率, 音量倍率, 延遲秒]; 級數越高音越高、層越多
  var ON_BEAT_LAYERS = {
    1: [[1.0, 1.0, 0]],
    2: [[1.2599, 1.1, 0], [1.0, 0.45, 0]],
    3: [[1.4983, 1.2, 0], [1.0, 0.5, 0], [2.0, 0.45, 0]]
  };

  // ---- 狀態 ----
  var ctx = null;
  var master = null, sfxBus = null, musicBus = null;
  var buffers = {};
  var musicBuf = {};       // 曲名 -> 解碼好的 AudioBuffer
  var inited = false;
  var muted = false;
  var pools = {};          // 沒有 Web Audio 時的 HTMLAudio 播放池
  var musicEls = {};       // 沒有 Web Audio 時的背景音樂元素
  var lastPlayed = {};     // 事件名 -> 最近一次播放的 performance 時間(毫秒)
  var latencyComp = true;  // 音樂是否補償輸出延遲(讓「聽到的」拍子對齊時鐘)
  var music = {
    name: null,       // 目前選定的曲名(暫停中也保留)
    source: null,
    gain: null,
    startCtx: 0,      // source 開始的 ctx 時間
    beatAtStart: 0,   // source 開始那一刻對應的「時鐘拍」
    playing: false,   // 正在走(含等待解碼中)
    pending: null,    // 解碼尚未完成時: { beat, ctxTime }
    el: null          // 退路: 目前的 HTMLAudio
  };

  function has(o, k) { return Object.prototype.hasOwnProperty.call(o, k); }
  function nowMs() {
    return (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
  }

  // ---- base64 / PCM ----
  function b64ToBytes(b64) {
    var bin = atob(b64);
    var out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  function b64ToFloat(b64) {
    var bin = atob(b64);
    var n = bin.length >> 1;
    var out = new Float32Array(n);
    for (var i = 0; i < n; i++) {
      var lo = bin.charCodeAt(i * 2), hi = bin.charCodeAt(i * 2 + 1);
      var v = (hi << 8) | lo;
      if (v >= 32768) v -= 65536;
      out[i] = v / 32768;
    }
    return out;
  }
  function makeBuffer(data, rate) {
    var b = ctx.createBuffer(1, data.length, rate);
    if (b.copyToChannel) b.copyToChannel(data, 0);
    else b.getChannelData(0).set(data);
    return b;
  }

  // ---- 背景音樂解碼(mp3 以 base64 內嵌, 不經 fetch; 載入時就用離線 context 先解) ----
  function calibrate(name, buf) {
    // 找第一個 |樣本| > 0.02 的位置, 與原始輸出檔比對, 校正解碼器開頭填充的差異
    var m = MUSIC[name];
    var lim = Math.min(buf.length, Math.floor(buf.sampleRate * 0.4));
    var idx = -1;
    for (var c = 0; c < buf.numberOfChannels; c++) {
      var d = buf.getChannelData(c);
      for (var i = 0; i < lim; i++) {
        if (d[i] > 0.02 || d[i] < -0.02) { if (idx < 0 || i < idx) idx = i; break; }
      }
    }
    var corr = idx >= 0 ? idx / buf.sampleRate - m.onset : 0;
    m.offset = (Math.abs(corr) <= 0.1) ? m.lead + corr : m.lead;
  }
  var decodeState = {};     // 曲名 -> 'busy' | 'done' | 'failed'
  function decodeWith(dctx, name, done) {
    var called = false;
    decodeState[name] = 'busy';
    function ok(buf) {
      if (called) return; called = true;
      try { calibrate(name, buf); musicBuf[name] = buf; decodeState[name] = 'done'; onMusicReady(name); }
      catch (e) { decodeState[name] = 'failed'; }
      done();
    }
    function fail() {
      if (called) return; called = true;
      decodeState[name] = 'failed';
      // 離線 context 解不了時, 若正式 context 已建立就再試一次
      if (ctx && dctx !== ctx) { decodeWith(ctx, name, done); return; }
      done();
    }
    try {
      var bytes = b64ToBytes(MUSIC_DATA[name]);
      var p = dctx.decodeAudioData(bytes.buffer, ok, fail);
      if (p && p.then) p.then(ok, fail);
    } catch (e) { fail(); }
  }
  // 依序解碼(第 1 首先), 跳過已完成或解碼中的
  function decodeAll(dctx) {
    var names = ['stage1', 'stage2', 'stage3'];
    var i = 0;
    (function next() {
      if (i >= names.length) return;
      var n = names[i++];
      var st = decodeState[n];
      if (st === 'done' || st === 'busy' || !MUSIC_DATA[n]) { next(); return; }
      decodeWith(dctx, n, next);
    })();
  }
  function preDecode() {
    try {
      if (typeof window === 'undefined') return;
      var OAC = window.OfflineAudioContext || window.webkitOfflineAudioContext;
      if (!OAC) return;
      var off = new OAC(2, 44100, 44100);
      decodeAll(off);
    } catch (e) {}
  }

  // ---- 初始化 ----
  function init() {
    if (inited) {
      if (ctx && ctx.state === 'suspended' && ctx.resume) { try { ctx.resume(); } catch (e) {} }
      return;
    }
    inited = true;
    var AC = (typeof window !== 'undefined') && (window.AudioContext || window.webkitAudioContext);
    if (AC) {
      try {
        ctx = new AC({ latencyHint: 'interactive' });
      } catch (e) {
        try { ctx = new AC(); } catch (e2) { ctx = null; }
      }
    }
    if (ctx) {
      try {
        master = ctx.createGain();
        master.gain.value = muted ? 0 : 1;
        master.connect(ctx.destination);
        sfxBus = ctx.createGain(); sfxBus.connect(master);
        musicBus = ctx.createGain(); musicBus.gain.value = MUSIC_VOL; musicBus.connect(master);
        for (var k in PCM_DATA) {
          if (has(PCM_DATA, k)) buffers[k] = makeBuffer(b64ToFloat(PCM_DATA[k]), PCM_RATE);
        }
        decodeAll(ctx);   // 沒有離線 context(或它解失敗)的曲子改用正式 context 解碼
        if (ctx.state === 'suspended' && ctx.resume) ctx.resume();
      } catch (e) {
        ctx = null;
      }
    }
    if (!ctx) buildPools();
  }
  function buildPools() {
    if (typeof Audio === 'undefined') return;
    for (var name in SFX) {
      if (!has(SFX, name)) continue;
      var arr = [];
      for (var i = 0; i < 4; i++) {
        try { var a = new Audio('audio/assets/' + SFX[name].file); a.preload = 'auto'; arr.push(a); } catch (e) {}
      }
      pools[name] = { list: arr, next: 0 };
    }
    for (var m in MUSIC) {
      if (!has(MUSIC, m)) continue;
      try { var el = new Audio('audio/assets/' + MUSIC[m].file); el.preload = 'auto'; musicEls[m] = el; } catch (e) {}
    }
  }

  // ---- 一次性音效 ----
  function playBuffer(bufName, vol, rate, delay, pan) {
    var buf = buffers[bufName];
    if (!buf) return;
    var src = ctx.createBufferSource();
    src.buffer = buf;
    src.playbackRate.value = rate || 1;
    var g = ctx.createGain();
    g.gain.value = vol;
    src.connect(g);
    var node = g;
    if (pan && ctx.createStereoPanner) {
      var p = ctx.createStereoPanner();
      p.pan.value = Math.max(-1, Math.min(1, pan));
      g.connect(p); node = p;
    }
    node.connect(sfxBus);
    src.start(ctx.currentTime + (delay || 0));
  }
  function play(name, opts) {
    try {
      if (!inited) return;
      if (typeof name !== 'string' || !has(SFX, name)) return;
      var def = SFX[name];
      opts = opts || {};
      var t = nowMs();
      var rate = 1, delay = 0, vol = def.vol;
      var pan = (typeof opts.x === 'number' && isFinite(opts.x)) ? ((opts.x - 640) / 640) * 0.6 : 0;
      var layers = null;
      if (name === 'countIn') {
        rate = COUNT_IN_RATE[opts.left] || 1;
        if (opts.left === 1) vol = Math.min(1, vol * 1.25);
      } else if (name === 'onBeat') {
        var step = Math.max(1, Math.min(3, (opts.step | 0) || 1));
        layers = ON_BEAT_LAYERS[step];
        rate = layers[0][0]; vol = Math.min(1, def.vol * layers[0][1]);
      } else if (name === 'netSwap') {
        // 同一刻兩次換網(例: 第 2 關跳位當下即判捕捉, 接著輪替)只響一次
        if (t - (lastPlayed.netSwap || -1e9) < 40) return;
        // 與捕捉同一刻 -> 稍晚 70 毫秒, 讓兩聲分得開
        if (t - (lastPlayed.catch || -1e9) < 50) delay = 0.07;
      } else if (name === 'danger') {
        if (t - (lastPlayed.danger || -1e9) < 1000) return;
      } else if (name === 'tutorialShow') {
        if (t - (lastPlayed.tutorialShow || -1e9) < 150) return;
      } else if (name === 'tutorialDone') {
        if (t - (lastPlayed.tutorialDone || -1e9) < 300) return;
        // 與捕捉 / 踩拍 / 整串同一刻(階段 3、5 的完成就是一次捕捉) -> 晚 0.15 秒, 排在遊戲回饋音後面
        var lastFb = Math.max(lastPlayed.catch || -1e9, lastPlayed.onBeat || -1e9, lastPlayed.beatChain || -1e9);
        if (t - lastFb < 50) delay = 0.15;
      }
      lastPlayed[name] = t;
      if (ctx) {
        if (layers) {
          for (var i = 0; i < layers.length; i++) {
            playBuffer(def.pcm, Math.min(1, def.vol * layers[i][1]), layers[i][0], layers[i][2], pan);
          }
          return;
        }
        playBuffer(def.pcm, vol, rate, delay, pan);
        if (name === 'beatChain') {
          // 整串: 在送進網的踩拍之後再往上跑兩個高音, 跟單次第 3 級分得開
          playBuffer('on_beat_glass', 0.6, 2.0, 0.1, pan);
          playBuffer('on_beat_glass', 0.55, 2.5198, 0.2, pan);
        }
        return;
      }
      // 退路: HTMLAudio 播放池
      var pool = pools[name];
      if (!pool || !pool.list.length || muted) return;
      var a = pool.list[pool.next];
      pool.next = (pool.next + 1) % pool.list.length;
      a.volume = Math.min(1, vol);
      if ('playbackRate' in a) a.playbackRate = rate;
      try { a.currentTime = 0; } catch (e) {}
      var pr = a.play();
      if (pr && pr.catch) pr.catch(function () {});
    } catch (e) { /* 不讓音效錯誤影響遊戲 */ }
  }

  // ---- 背景音樂 ----
  // 時鐘拍 -> 歌曲秒數(有循環區段的曲子超過終點就繞回起點; 目前三首都沒有); 不循環的曲子超過曲長回 null(歌已結束)
  function songPosForBeat(m, beat) {
    var pos = (beat - SONG_START_BEAT) * m.beatSec;
    if (pos < 0) pos = 0;
    if (m.loop) {
      if (pos >= m.loop.end) {
        var len = m.loop.end - m.loop.start;
        pos = m.loop.start + ((pos - m.loop.start) % len);
      }
      return pos;
    }
    return pos < m.songSec ? pos : null;
  }
  function outLatency() {
    if (!ctx) return 0;
    var v = (ctx.outputLatency || 0) + (ctx.baseLatency || 0);
    return isFinite(v) ? v : 0;
  }
  function stopSource(fadeSec) {
    if (!music.source) return;
    var s = music.source, g = music.gain;
    music.source = null; music.gain = null;
    try {
      var t = ctx.currentTime;
      g.gain.cancelScheduledValues(t);
      g.gain.setValueAtTime(g.gain.value, t);
      g.gain.linearRampToValueAtTime(0, t + fadeSec);
      s.stop(t + fadeSec + 0.02);
    } catch (e) { try { s.stop(); } catch (e2) {} }
  }
  // 讓音樂「此刻」對到時鐘拍 beat(可為小數)
  function startAt(name, beat, fadeIn) {
    var m = MUSIC[name];
    music.name = name;
    music.playing = true;
    music.startCtx = ctx.currentTime;
    music.beatAtStart = beat;
    var buf = musicBuf[name];
    if (!buf) { music.pending = { beat: beat, ctxTime: ctx.currentTime }; return; }
    music.pending = null;
    var comp = latencyComp ? outLatency() : 0;
    // 延遲補償: 聲音要過 comp 秒才被聽到, 所以從「beat + comp」的位置開始播
    var pos = songPosForBeat(m, beat + comp / m.beatSec);
    if (pos === null) return;      // 不循環的曲子已播完: 保持靜默, 時鐘照走
    var t0 = ctx.currentTime;
    var src = ctx.createBufferSource();
    src.buffer = buf;
    if (m.loop) {
      src.loop = true;
      src.loopStart = m.offset + m.loop.start;
      src.loopEnd = m.offset + m.loop.end;
    }
    var g = ctx.createGain();
    src.connect(g); g.connect(musicBus);
    g.gain.setValueAtTime(fadeIn ? 0 : 1, t0);
    if (fadeIn) g.gain.linearRampToValueAtTime(1, t0 + fadeIn);
    src.start(t0, m.offset + pos);
    music.source = src; music.gain = g;
  }
  function onMusicReady(name) {
    if (!ctx || !music.pending || music.name !== name || !music.playing) return;
    var m = MUSIC[name];
    var beat = music.pending.beat + (ctx.currentTime - music.pending.ctxTime) / m.beatSec;
    startAt(name, beat, 0.03);
  }

  // ---- 退路: HTMLAudio 背景音樂(不保證循環無縫) ----
  function elStop() {
    if (music.el) { try { music.el.pause(); } catch (e) {} }
    music.el = null;
  }
  function elStart(name, beat) {
    var m = MUSIC[name], el = musicEls[name];
    elStop();
    music.name = name; music.playing = true;
    music.beatAtStart = beat; music.startCtx = nowMs() / 1000;
    if (!el) return;
    var pos = songPosForBeat(m, beat);
    if (pos === null) return;
    try { el.currentTime = m.lead + pos; } catch (e) {}
    el.volume = muted ? 0 : MUSIC_VOL;
    el.ontimeupdate = m.loop ? function () {
      if (el.currentTime >= m.lead + m.loop.end) el.currentTime -= (m.loop.end - m.loop.start);
    } : null;
    music.el = el;
    var pr = el.play();
    if (pr && pr.catch) pr.catch(function () {});
  }

  function playMusic(name, opts) {
    try {
      if (!inited) return;
      if (typeof name !== 'string' || !has(MUSIC, name)) return;
      var beat = (opts && typeof opts.beat === 'number' && isFinite(opts.beat)) ? opts.beat : SONG_START_BEAT;
      if (!ctx) { elStart(name, beat); return; }
      var hadOther = music.source && music.name !== name;
      stopSource(hadOther ? 0.3 : 0.015);
      startAt(name, beat, 0.015);
    } catch (e) {}
  }
  function stopMusic() {
    try {
      music.playing = false; music.pending = null;
      if (!ctx) { elStop(); music.name = null; return; }
      stopSource(0.15);
      music.name = null;
    } catch (e) {}
  }
  function pauseMusic() {
    try {
      music.playing = false; music.pending = null;
      if (!ctx) { elStop(); return; }
      stopSource(0.03);
    } catch (e) {}
  }
  // 恢復 / 校正: 讓音樂此刻對到時鐘拍 beat
  function seekMusic(beat) {
    try {
      if (!inited || !music.name || typeof beat !== 'number' || !isFinite(beat)) return;
      if (!ctx) { elStart(music.name, beat); return; }
      stopSource(0.015);
      startAt(music.name, beat, 0.015);
    } catch (e) {}
  }
  // 目前音樂(聽到的)對應的時鐘拍; 沒在播回 null
  function getMusicBeat() {
    if (!music.playing || !music.name) return null;
    var m = MUSIC[music.name];
    if (!ctx) {
      if (!music.el) return null;
      return SONG_START_BEAT + (music.el.currentTime - m.lead) / m.beatSec;
    }
    return music.beatAtStart + (ctx.currentTime - music.startCtx) / m.beatSec;
  }
  // 每拍(或每幀)由 RD 傳入時鐘拍; 偏差超過容許值就把音樂對回時鐘。回傳偏差秒數(音樂 - 時鐘)
  function syncMusic(beat, toleranceSec) {
    try {
      if (!inited || !music.playing || !music.name || typeof beat !== 'number' || !isFinite(beat)) return 0;
      var m = MUSIC[music.name];
      if (!m.loop && songPosForBeat(m, beat) === null) return 0;   // 不循環的曲子已播完
      var tol = (typeof toleranceSec === 'number') ? toleranceSec : (ctx ? 0.04 : 0.12);
      var mb = getMusicBeat();
      if (mb === null) return 0;
      var drift;
      if (!ctx && m.loop && beat >= 0) {
        // 退路循環: 用歌曲位置比對
        drift = (songPosForBeat(m, mb) - songPosForBeat(m, beat));
      } else {
        drift = (mb - beat) * m.beatSec;
      }
      if (Math.abs(drift) > tol) seekMusic(beat);
      return drift;
    } catch (e) { return 0; }
  }
  function getMusicInfo(name) {
    if (typeof name !== 'string' || !has(MUSIC, name)) return null;
    var m = MUSIC[name];
    return {
      file: 'audio/assets/' + m.file,                      // 曲檔(相對 index.html)
      bpm: m.bpm, beatSec: m.beatSec, bars: m.bars, levelBars: m.levelBars,
      songStartBeat: SONG_START_BEAT, lengthSec: m.songSec,
      firstBeatInFileSec: m.lead,                          // 第一拍(預備拍第 -4 拍)在音檔中的秒數
      levelStartInFileSec: m.lead + 4 * m.beatSec,         // 關內第 0 拍在音檔中的秒數
      loop: !!m.loop, loopStartBeat: m.loop ? 0 : null, loopBeats: m.loop ? m.levelBars * 4 : null,
      loopStartInFileSec: m.loop ? m.lead + m.loop.start : null,   // 循環起點在音檔中的秒數
      loopEndInFileSec: m.loop ? m.lead + m.loop.end : null        // 循環終點在音檔中的秒數
    };
  }
  function isMusicReady(name) {
    if (!inited) return false;
    if (!ctx) return !!musicEls[name];
    return !!musicBuf[name];
  }

  // ---- 靜音 ----
  function setMuted(b) {
    muted = !!b;
    try {
      if (master && ctx) {
        var t = ctx.currentTime;
        master.gain.cancelScheduledValues(t);
        master.gain.setValueAtTime(master.gain.value, t);
        master.gain.linearRampToValueAtTime(muted ? 0 : 1, t + 0.02);
      }
      if (music.el) music.el.volume = muted ? 0 : MUSIC_VOL;
      if (muted) {
        for (var k in pools) {
          if (!has(pools, k)) continue;
          for (var i = 0; i < pools[k].list.length; i++) { try { pools[k].list[i].pause(); } catch (e) {} }
        }
      }
    } catch (e) {}
  }
  function isMuted() { return muted; }

  window.Sound = {
    init: init,
    play: play,
    playMusic: playMusic,
    stopMusic: stopMusic,
    setMuted: setMuted,
    isMuted: isMuted,
    // 拍子對齊介面(見 sound.md「背景音樂與拍子時鐘」)
    pauseMusic: pauseMusic,
    resumeMusic: seekMusic,
    seekMusic: seekMusic,
    syncMusic: syncMusic,
    getMusicBeat: getMusicBeat,
    getMusicInfo: getMusicInfo,
    isMusicReady: isMusicReady,
    getOutputLatency: outLatency,
    setMusicLatencyCompensation: function (on) { latencyComp = !!on; },
    SONG_START_BEAT: SONG_START_BEAT
  };

  // ---- 內嵌短音效(16-bit PCM, 單聲道, 22050 Hz, base64)----
  var PCM_DATA = {
    count_in_pluck: "",
    on_beat_glass: "",
    beat_chain_powerup: "",
    catch_confirm: "",
    net_swap_phaser_up: "",
    expire_phaser_down: "",
    danger_jingle: "",
    stage_change_steel: "",
    floor_rotate_switch: "",
    wrong_dye_error: "",
    tutorial_show_drop: "",
    tutorial_done_confirm: ""
  };
  // ---- 內嵌背景音樂(mp3, 與 assets/ 同檔, base64)----
  var MUSIC_DATA = {
    stage1: "",
    stage2: "",
    stage3: ""
  };
  preDecode();
})();
